257	type persistTerm struct {
258		Wire  int    `json:"wire"`
259		Coeff string `json:"coeff"`
260	}
261	
262	type persistConstraint struct {
263		A []persistTerm `json:"a"`
264		B []persistTerm `json:"b"`
265		C []persistTerm `json:"c"`
266	}
267	
268	// persistDefinition is the canonical, already-validated constraint set bound
269	// to one circuit version. The public/private partition is owned by the
270	// circuit record and is deliberately not duplicated here, so it can never
271	// drift from the declared counts.
272	type persistDefinition struct {
273		Modulus     string              `json:"modulus"`
274		Constraints []persistConstraint `json:"constraints"`
275	}
276	
277	// persistArtifact is a compiled artifact: the version's identity and
278	// constraint count bound to its recomputable SHA-256 hash.
279	type persistArtifact struct {
280		Name        string `json:"name"`
281		Version     int    `json:"version"`
282		Modulus     int64  `json:"modulus"`
283		Constraints int    `json:"constraints"`
284		Hash        string `json:"hash"`
285	}
286	
287	type persistCircuit struct {
288		Name          string             `json:"name"`
289		Version       int                `json:"version"`
290		Constraints   int                `json:"constraints"`
291		PublicInputs  int                `json:"public_inputs"`
292		PrivateInputs int                `json:"private_inputs"`
293		Frozen        bool               `json:"frozen"`
294		Description   string             `json:"description"`
295		Definition    *persistDefinition `json:"definition,omitempty"`
296	}
297	
298	// Strict decoding of committed circuit records.
299	//
300	// A circuit record in data.json must name each of name, version, constraints,
301	// public_inputs, private_inputs, frozen and description exactly once, with
302	// the exact JSON type the writer emits (string / integer / integer / integer
303	// / integer / boolean / string). A missing key, a null, a wrong type or a
304	// repeated key is data corruption and refuses the whole directory read: a
305	// missing or null frozen flag must not silently read as false (turning a
306	// frozen version back into an editable draft), and a repeated key must not
307	// resolve to its last value. An explicit 0, false or "" is an ordinary value
308	// and stays legal. The definition member remains the one optional field: it
309	// may be absent or null (the legacy counts-only state); when present it goes
310	// through the strict persistDefinition decoder.
311	//
312	// Only shape is judged here. The domain rules (non-blank name, positive
313	// version and constraint count, non-negative input counts) keep being
314	// re-checked by validateEnvelope.
315	
316	var persistCircuitFields = []string{
317		"name", "version", "constraints", "public_inputs", "private_inputs",
318		"frozen", "description", "definition",
319	}
320	
321	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
322	// tagged for committed data: every structural failure in a stored circuit
323	// record is data corruption, never a bad request.
324	var storedRecordShape = jsonShape{fail: corruptf}
325	
326	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
327		const what = "stored circuit record"
328		if string(bytes.TrimSpace(raw)) == "null" {
329			return corruptf("%s must be a JSON object, not null", what)
330		}
331		members, err := strictCircuitObject(raw, what)
332		if err != nil {
333			return err
334		}
335	
336		var out persistCircuit
337	
338		requireString := func(key string, dst *string) error {
339			r, err := storedRecordShape.require(members, key, what)
340			if err != nil {
341				return err
342			}
343			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
344			if err != nil {
345				return err
346			}
347			*dst = v
348			return nil
349		}
350		requireInt := func(key string, dst *int) error {
351			r, err := storedRecordShape.require(members, key, what)
352			if err != nil {
353				return err
354			}
355			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
356			if err != nil {
357				return err
358			}
359			*dst = v
360			return nil
361		}
362	
363		if err := requireString("name", &out.Name); err != nil {
364			return err
365		}
366		if err := requireInt("version", &out.Version); err != nil {
367			return err
368		}
369		if err := requireInt("constraints", &out.Constraints); err != nil {
370			return err
371		}
372		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
373			return err
374		}
375		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
376			return err
377		}
378		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
379		if err != nil {
380			return err
381		}
382		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
383		if err != nil {
384			return err
385		}
386		if err := requireString("description", &out.Description); err != nil {
387			return err
388		}
389	
390		// definition is the only optional member: absent or null both mean the
391		// counts-only legacy state.
392		if defRaw, present := members["definition"]; present {
393			if string(bytes.TrimSpace(defRaw)) != "null" {
394				var def persistDefinition
395				if err := json.Unmarshal(defRaw, &def); err != nil {
396					var se StoreError
397					if errors.As(err, &se) {
398						return err // already reported as data corruption
399					}
400					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
401				}
402				out.Definition = &def
403			}
404		}
405	
406		*c = out
407		return nil
408	}
409	
410	// strictCircuitObject decodes one committed circuit record's own member map,
411	// demanding a JSON object with exactly the known top-level fields once.
412	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
413		return strictObjectMembers(raw, what, persistCircuitFields)
414	}
415	
416	// strictObjectMembers decodes one committed record's own member map,
417	// demanding a JSON object without repeated keys. A non-nil allowed list
418	// restricts which keys may appear; nil allows any key. It scans only the
419	// record's own level: the envelope scanner already attributes a duplicated
420	// top-level key to this record, and nested values such as the constraint
421	// definition own their (more precise) strict decoders. Keys are compared
422	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
423	// still a duplicate, even when both values are identical.
424	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
425		trimmed := bytes.TrimSpace(raw)
426		if len(trimmed) == 0 || trimmed[0] != '{' {
427			return nil, corruptf("%s must be a JSON object", what)
428		}
429		dec := json.NewDecoder(bytes.NewReader(trimmed))
430		dec.UseNumber()
431		open, err := dec.Token()
432		if err != nil || open != json.Delim('{') {
433			return nil, corruptf("%s must be a JSON object", what)
434		}
435		var allowed map[string]bool
436		if allowedFields != nil {
437			allowed = make(map[string]bool, len(allowedFields))
438			for _, f := range allowedFields {
439				allowed[f] = true
440			}
441		}
442		members := make(map[string]json.RawMessage)
443		for dec.More() {
444			keyTok, err := dec.Token()
445			if err != nil {
446				return nil, corruptf("%s is not valid JSON: %v", what, err)
447			}
448			key, ok := keyTok.(string)
449			if !ok {
450				return nil, corruptf("%s is not valid JSON", what)
451			}
452			if allowed != nil && !allowed[key] {
453				return nil, corruptf("%s has unknown field %q", what, key)
454			}
455			if _, repeated := members[key]; repeated {
456				return nil, corruptf("%s contains duplicate field %q", what, key)
457			}
458			var value json.RawMessage
459			if err := dec.Decode(&value); err != nil {
460				return nil, corruptf("%s is not valid JSON: %v", what, err)
461			}
462			members[key] = value
463		}
464		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
465			return nil, corruptf("%s is not valid JSON", what)
466		}
467		if _, err := dec.Token(); err != io.EOF {
468			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
469		}
470		return members, nil
471	}
472	
473	type persistSetup struct {
474		Name    string `json:"name"`
475		Version int    `json:"version"`
476	}
477	
478	type persistJob struct {
479		ID       string `json:"id"`
480		Circuit  string `json:"circuit"`
481		Version  int    `json:"version"`
482		Kind     string `json:"kind"`
483		Attempt  int    `json:"attempt"`
484		Artifact string `json:"artifact,omitempty"`
485		// CompiledHash is the optional binding to the pinned version's compiled
486		// artifact, stored exactly as submitted.
487		CompiledHash string `json:"compiled_hash,omitempty"`
488	}
489	
490	// Strict decoding of the compiled-artifact binding on a committed job record.
491	//
492	// compiled_hash is a field whose presence is meaningful: records written
493	// before bindings existed simply omit it, and an explicit "" is the unbound
494	// state. But once the key appears its value must be a JSON string. A null is
495	// not "no binding" — it is damage to a binding the record claims to carry,
496	// and so is a number, boolean, array or object in its place. Reading either
497	// as the zero string would silently turn a bound job into an unbound one
498	// (and the next commit would drop the field entirely), so the read is
499	// refused as data corruption instead. A repeated key — including one
500	// repeated through JSON string escapes, even with identical values — is
501	// likewise refused rather than resolved to its last value. A legal non-empty
502	// string keeps being matched against the pinned version's artifact by
503	// validateEnvelope, exactly as written.
504	//
505	// Only the binding field is judged here; every other field keeps the
506	// ordinary struct decoding.
507	func (j *persistJob) UnmarshalJSON(raw []byte) error {
508		const what = "stored job record"
509		if string(bytes.TrimSpace(raw)) == "null" {
510			return corruptf("%s must be a JSON object, not null", what)
511		}
512		members, err := strictObjectMembers(raw, what, nil)
513		if err != nil {
514			return err
515		}
516		// Name the job in a binding-field failure when its id is legible; the id
517		// itself is decoded for real by the ordinary pass below.
518		where := what
519		if idRaw, ok := members["id"]; ok {
520			if id, idErr := storedRecordShape.string(idRaw, what+` field "id"`); idErr == nil {
521				where = fmt.Sprintf("stored job record %q", id)
522			}
523		}
524		compiledHash := ""
525		hasBinding := false
526		if hashRaw, present := members["compiled_hash"]; present {
527			hash, err := storedRecordShape.string(hashRaw, where+` field "compiled_hash"`)
528			if err != nil {
529				return err
530			}
531			compiledHash, hasBinding = hash, true
532		}
533		type plainJob persistJob
534		var decoded plainJob
535		if err := json.Unmarshal(raw, &decoded); err != nil {
536			return corruptf("%s is not valid JSON: %v", what, err)
537		}
538		if hasBinding {
539			decoded.CompiledHash = compiledHash
540		}
541		*j = persistJob(decoded)
542		return nil
543	}
544	
545	// Store is a persistent workbench backed by one local data directory.
546	//
547	// All operations are safe for concurrent use by multiple goroutines and by
548	// several processes pointed at the same directory: an in-process mutex plus a
549	// process-shared flock serialize commits, and every commit is an atomic
550	// temp-file/fsync/rename replacement. Open the directory with Open and call
551	// Close when done.
552	type Store struct {
553		dir  string
554		mu   sync.Mutex
555		lock *os.File
556	
557		data envelope
558	}
559	
560	// Open opens (creating if needed) the workbench data in dir. If the
561	// directory does not exist it is created. Existing committed data is loaded
562	// and fully validated before Open returns; on a corrupt, truncated or
563	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
564	// leaves every file in the directory untouched.
565	func Open(dir string) (*Store, error) {
566		if dir == "" {
567			return nil, invalidf("data directory must not be empty")
568		}
569		if err := os.MkdirAll(dir, 0o755); err != nil {
570			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
571		}
572		lockPath := filepath.Join(dir, dirLockFile)
573		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
574		if err != nil {
575			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
576		}
577		// Serialize against other processes while we read / validate.
578		if err := lockExclusive(lock); err != nil {
579			lock.Close()
580			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
581		}
582	
583		s := &Store{dir: dir, lock: lock}
584		if err := s.loadLocked(); err != nil {
585			unlockLock(lock)
586			lock.Close()
587			return nil, err
588		}
589		// The lock is taken again per operation; holding it for the store's
590		// lifetime would forbid two open handles on one directory.
591		if err := unlockLock(lock); err != nil {
592			lock.Close()
593			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
594		}
595		return s, nil
596	}
597	
598	// Close releases the directory lock. It does not discard committed data.
599	func (s *Store) Close() error {
600		s.mu.Lock()
601		defer s.mu.Unlock()
602		if s.lock == nil {
603			return nil
604		}
605		var first error
606		if err := unlockLock(s.lock); err != nil {
607			first = err
608		}
609		if err := s.lock.Close(); err != nil && first == nil {
610			first = err
611		}
612		s.lock = nil
613		return first
614	}
615	
616	// Dir reports the data directory backing the store.
617	func (s *Store) Dir() string { return s.dir }
618	
619	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
620	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
621	
622	// loadLocked reads and validates the committed file. Caller must hold the
623	// exclusive flock; the in-process mutex is taken by the public Open path.
624	func (s *Store) loadLocked() error {
625		raw, err := os.ReadFile(s.dataPath())
626		if errors.Is(err, os.ErrNotExist) {
627			s.data = envelope{Format: FormatVersion}
628			return nil
629		}
630		if err != nil {
631			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
632		}
633		if len(strings.TrimSpace(string(raw))) == 0 {
634			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
635		}
636	
637		var env envelope
638		if err := json.Unmarshal(raw, &env); err != nil {
639			// Shape failures surfaced by the persisted-definition decoders are
640			// integrity failures, not JSON syntax errors; report their detail
641			// instead of the generic "not valid JSON" wording.
642			var se StoreError
643			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
644				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
645			}
646			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
647		}
648		if env.Format == 0 {
649			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
650		}
651		if env.Format != FormatVersion {
652			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
653				s.dataPath(), env.Format, FormatVersion)
654		}
655		if err := validateEnvelope(env); err != nil {
656			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
657		}
658		s.data = env
659		return nil
660	}
661	
662	// commitLocked writes the pending state atomically: temp file → fsync →
663	// rename → fsync directory. Caller must hold both the in-process mutex and
664	// the exclusive flock; all in-memory mutations must already have happened and
665	// been rule-checked, so a failure here occurs before any success is reported.
666	func (s *Store) commitLocked() error {
667		s.data.Format = FormatVersion
668		// Stable output: records are stored sorted so files are deterministic.
669		sortEnvelope(&s.data)
670	
671		payload, err := json.MarshalIndent(&s.data, "", "  ")
672		if err != nil {
673			return fmt.Errorf("cannot encode data: %w", err)
674		}
675		payload = append(payload, '\n')
676	
677		tmp := s.tmpPath()
678		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
679		if err != nil {
680			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
681		}
682		if _, err := f.Write(payload); err != nil {
683			f.Close()
684			os.Remove(tmp)
685			return fmt.Errorf("cannot write staged data: %w", err)
686		}
687		if err := f.Sync(); err != nil {
688			f.Close()
689			os.Remove(tmp)
690			return fmt.Errorf("cannot flush staged data: %w", err)
691		}
692		if err := f.Close(); err != nil {
693			os.Remove(tmp)
694			return fmt.Errorf("cannot finish staged data: %w", err)
695		}
696		if err := os.Rename(tmp, s.dataPath()); err != nil {
697			os.Remove(tmp)
698			return fmt.Errorf("cannot commit data file: %w", err)
699		}
700		if err := syncDir(s.dir); err != nil {
701			// The rename already happened; lack of dir fsync only weakens crash
702			// durability, never correctness of what is visible now.
703			return nil
704		}
705		return nil
706	}
707	
708	// withLock runs fn under the in-process mutex and an exclusive flock, then
709	// atomically commits when fn requests it. The on-disk state is re-read after
710	// acquiring the lock, so concurrent commits from another process or another
711	// handle are always observed. Operations validate before mutating; a rejected
712	// operation (commit=false or an error) writes nothing and leaves committed
713	// state unchanged.
714	func (s *Store) withLock(fn func() (commit bool, err error)) error {
715		s.mu.Lock()
716		defer s.mu.Unlock()
717		if s.lock == nil {
718			return invalidf("store is closed")
719		}
720		if err := lockExclusive(s.lock); err != nil {
721			return fmt.Errorf("cannot lock data directory: %w", err)
722		}
723		defer unlockLock(s.lock)
724	
725		if err := s.loadLocked(); err != nil {
726			return err
727		}
728		commit, err := fn()
729		if err != nil {
730			return err
731		}
732		if !commit {
733			return nil
734		}
735		return s.commitLocked()
736	}
737	
738	// withLockRead runs fn under a shared flock over freshly reloaded state.
739	func (s *Store) withLockRead(fn func() error) error {
740		s.mu.Lock()
741		defer s.mu.Unlock()
742		if s.lock == nil {
743			return invalidf("store is closed")
744		}
745		if err := lockShared(s.lock); err != nil {
746			return fmt.Errorf("cannot lock data directory: %w", err)
747		}
748		defer unlockLock(s.lock)
749		if err := s.loadLocked(); err != nil {
750			return err
751		}
752		return fn()
753	}
754	
755	func sortEnvelope(env *envelope) {
756		sort.Slice(env.Circuits, func(i, j int) bool {
757			if env.Circuits[i].Name != env.Circuits[j].Name {
758				return env.Circuits[i].Name < env.Circuits[j].Name
759			}
760			return env.Circuits[i].Version < env.Circuits[j].Version
761		})
762		sort.Slice(env.Setups, func(i, j int) bool {
763			if env.Setups[i].Name != env.Setups[j].Name {
764				return env.Setups[i].Name < env.Setups[j].Name
765			}
766			return env.Setups[i].Version < env.Setups[j].Version
767		})
768		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
769		sort.Slice(env.Artifacts, func(i, j int) bool {
770			if env.Artifacts[i].Name != env.Artifacts[j].Name {
771				return env.Artifacts[i].Name < env.Artifacts[j].Name
772			}
773			return env.Artifacts[i].Version < env.Artifacts[j].Version
774		})
775	}
776	
777	// validateEnvelope re-checks every invariant on load so a tampered or
778	// hand-edited file cannot bypass the domain rules.
779	func validateEnvelope(env envelope) error {
780		seenCircuit := make(map[[2]string]bool)
781		circuitOK := make(map[[2]string]bool)
782		for i, c := range env.Circuits {
783			key := [2]string{c.Name, itoa(c.Version)}
784			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
785				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
786			}
787			if c.Version <= 0 {
788				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
789			}
790			if seenCircuit[key] {
791				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
792			}
793			seenCircuit[key] = true
794			if c.Constraints <= 0 {
795				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
796			}
797			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
798				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
799			}
800			if c.Definition != nil {
801				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
802					return err
803				}
804			}
805			circuitOK[key] = true
806		}
807		seenSetup := make(map[[2]string]bool)
808		for i, p := range env.Setups {
809			key := [2]string{p.Name, itoa(p.Version)}
810			if !circuitOK[key] {
811				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
812			}
813			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
814			if c == nil || !c.Frozen {
815				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
816			}
817			if seenSetup[key] {
818				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
819			}
820			seenSetup[key] = true
821		}
822		seenJob := make(map[string]bool)
823		for i, j := range env.Jobs {
824			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
825				return fmt.Errorf("job #%d has an empty or blank id", i+1)
826			}
827			if seenJob[j.ID] {
828				return fmt.Errorf("job %q appears more than once", j.ID)
829			}
830			seenJob[j.ID] = true
831			if j.Kind != "prove" {
832				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
833			}
834			if j.Attempt <= 0 {
835				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
836			}
837			key := [2]string{j.Circuit, itoa(j.Version)}
838			if !circuitOK[key] {
839				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
840			}
841			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
842			if c == nil || !c.Frozen {
843				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
844			}
845			if !seenSetup[key] {
846				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
847			}
848			// A recorded compiled-artifact binding must still resolve against the
849			// pinned version's artifact; a dangling or mismatched binding makes
850			// the file unreadable rather than silently dropping the binding.
851			if j.CompiledHash != "" {
852				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
853				if artifact == nil {
854					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
855				}
856				if artifact.Hash != j.CompiledHash {
857					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
858						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
859				}
860			}
861		}
862		seenArtifact := make(map[[2]string]bool)
863		for i, a := range env.Artifacts {
864			key := [2]string{a.Name, itoa(a.Version)}
865			if !circuitOK[key] {
866				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
867			}
868			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
869			if c == nil || !c.Frozen {
870				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
871			}
872			if seenArtifact[key] {
873				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
874			}
875			seenArtifact[key] = true
876			if c.Definition == nil {
877				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
878			}
879			if a.Constraints != c.Constraints {
880				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
881					a.Name, a.Version, a.Constraints, c.Constraints)
882			}
883			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
884			if err != nil {
885				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
886			}
887			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
888				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
889			}
890			wantHash := artifactHash(a.Name, a.Version, def)
891			if a.Hash != wantHash {
892				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
893					a.Name, a.Version, a.Hash, wantHash)
894			}
895		}
896		return nil
897	}
898	
899	// validatePersistDefinition re-validates a stored definition against its
900	// version's declared counts: prime modulus, in-range wires and an exact
901	// constraint count match.
902	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
903		parsed, err := definitionFromPersist(*def, public, private)
904		if err != nil {
905			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
906		}
907		if !parsed.compatibleWith(constraints, public, private) {
908			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
909		}
910		return nil
911	}
912	
913	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
914		for i := range cs {
915			if cs[i].Name == name && cs[i].Version == version {
916				return &cs[i]
917			}
918		}
919		return nil
920	}
921	
922	func itoa(v int) string { return fmt.Sprintf("%d", v) }
923

