1	package zkcircuit
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"testing"
9	)
10	
11	// These tests pin the read-time contract for a constraint definition that is
12	// already committed in data.json: its required fields and their types must
13	// match what the importer writes. A missing field or a null must never be
14	// read as a legitimate zero value (an empty side array, wire 0), because the
15	// two cases are indistinguishable after a plain struct decode even though
16	// only the first is a real definition.
17	
18	// readGenericEnv loads data.json as a generic JSON value so a test can
19	// damage individual fields without relying on byte offsets.
20	func readGenericEnv(t *testing.T, dir string) map[string]any {
21		t.Helper()
22		raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
23		if err != nil {
24			t.Fatal(err)
25		}
26		var env map[string]any
27		if err := json.Unmarshal(raw, &env); err != nil {
28			t.Fatal(err)
29		}
30		return env
31	}
32	
33	func writeGenericEnv(t *testing.T, dir string, env map[string]any) []byte {
34		t.Helper()
35		raw, err := json.MarshalIndent(env, "", "  ")
36		if err != nil {
37			t.Fatal(err)
38		}
39		raw = append(raw, '\n')
40		if err := os.WriteFile(filepath.Join(dir, dirDataFile), raw, 0o644); err != nil {
41			t.Fatal(err)
42		}
43		return raw
44	}
45	
46	// firstDefinition walks to the first circuit's definition object.
47	func firstDefinition(t *testing.T, env map[string]any) map[string]any {
48		t.Helper()
49		circuit := env["circuits"].([]any)[0].(map[string]any)
50		def, ok := circuit["definition"].(map[string]any)
51		if !ok {
52			t.Fatalf("seeded circuit has no definition object: %v", circuit["definition"])
53		}
54		return def
55	}
56	
57	// TestCorruptPersistedDefinitionRefused damages each required field in turn
58	// and requires Open to refuse the whole directory. The judgment must not
59	// depend on the version being frozen or already compiled, so every shape is
60	// damaged against both a draft (never compiled) and a frozen+compiled store.
61	func TestCorruptPersistedDefinitionRefused(t *testing.T) {
62		const goodDef = `{"modulus":"7","constraints":[
63			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"6"}]}]}`
64	
65		tamperDef := func(mut func(def map[string]any)) func(map[string]any) {
66			return func(env map[string]any) { mut(firstDefinition(t, env)) }
67		}
68		setSideTerm := func(side string, mut func(term map[string]any)) func(map[string]any) {
69			return tamperDef(func(def map[string]any) {
70				con := def["constraints"].([]any)[0].(map[string]any)
71				term := con[side].([]any)[0].(map[string]any)
72				mut(term)
73			})
74		}
75		setConstraint := func(mut func(con map[string]any)) func(map[string]any) {
76			return tamperDef(func(def map[string]any) {
77				mut(def["constraints"].([]any)[0].(map[string]any))
78			})
79		}
80		setCircuitField := func(field string, value any) func(map[string]any) {
81			return func(env map[string]any) {
82				circuit := env["circuits"].([]any)[0].(map[string]any)
83				circuit[field] = value
84			}
85		}
86	
87		damage := []struct {
88			name   string
89			mutate func(map[string]any)
90		}{
91			{"missing modulus", tamperDef(func(d map[string]any) { delete(d, "modulus") })},
92			{"null modulus", tamperDef(func(d map[string]any) { d["modulus"] = nil })},
93			{"non-string modulus", tamperDef(func(d map[string]any) { d["modulus"] = 7 })},
94			{"missing constraints", tamperDef(func(d map[string]any) { delete(d, "constraints") })},
95			{"null constraints", tamperDef(func(d map[string]any) { d["constraints"] = nil })},
96			{"non-array constraints", tamperDef(func(d map[string]any) { d["constraints"] = map[string]any{} })},
97			{"null constraint element", tamperDef(func(d map[string]any) { d["constraints"].([]any)[0] = nil })},
98			{"missing side a", setConstraint(func(c map[string]any) { delete(c, "a") })},
99			{"missing side b", setConstraint(func(c map[string]any) { delete(c, "b") })},
100			{"missing side c", setConstraint(func(c map[string]any) { delete(c, "c") })},
101			{"null side", setConstraint(func(c map[string]any) { c["a"] = nil })},
102			{"side not array", setConstraint(func(c map[string]any) { c["a"] = map[string]any{} })},
103			{"null term element", setConstraint(func(c map[string]any) { c["a"].([]any)[0] = nil })},
104			{"term not object", setConstraint(func(c map[string]any) { c["a"].([]any)[0] = 5 })},
105			{"term missing wire", setSideTerm("a", func(term map[string]any) { delete(term, "wire") })},
106			{"term null wire", setSideTerm("a", func(term map[string]any) { term["wire"] = nil })},
107			{"term string wire", setSideTerm("a", func(term map[string]any) { term["wire"] = "0" })},
108			{"term float wire", setSideTerm("a", func(term map[string]any) { term["wire"] = 1.5 })},
109			{"term missing coeff", setSideTerm("a", func(term map[string]any) { delete(term, "coeff") })},
110			{"term null coeff", setSideTerm("a", func(term map[string]any) { term["coeff"] = nil })},
111			{"term numeric coeff", setSideTerm("a", func(term map[string]any) { term["coeff"] = 1 })},
112			{"unknown term field", setSideTerm("a", func(term map[string]any) { term["q"] = 1 })},
113			{"definition not object", setCircuitField("definition", 5)},
114		}
115	
116		for _, frozen := range []bool{false, true} {
117			state := "draft"
118			if frozen {
119				state = "frozen-compiled"
120			}
121			t.Run(state, func(t *testing.T) {
122				for _, tc := range damage {
123					t.Run(tc.name, func(t *testing.T) {
124						dir := filepath.Join(t.TempDir(), "bench")
125						s, err := Open(dir)
126						if err != nil {
127							t.Fatal(err)
128						}
129						seedDraftWithDef(t, s, "c", 1, 1, 1, goodDef)
130						if frozen {
131							if _, err := s.FreezeCircuit("c", 1); err != nil {
132								t.Fatal(err)
133							}
134							if _, err := s.CompileCircuit("c", 1); err != nil {
135								t.Fatal(err)
136							}
137						}
138						if err := s.Close(); err != nil {
139							t.Fatal(err)
140						}
141	
142						env := readGenericEnv(t, dir)
