30		}
31		const goodDef = `{"modulus":"7","constraints":[
32			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"6"}]}]}`
33		seedDraftWithDef(t, s, "mul", 1, 1, 1, goodDef)
34		if frozen {
35			if _, err := s.FreezeCircuit("mul", 1); err != nil {
36				t.Fatal(err)
37			}
38			if _, err := s.RecordSetup("mul", 1); err != nil {
39				t.Fatal(err)
40			}
41			if _, err := s.CompileCircuit("mul", 1); err != nil {
42				t.Fatal(err)
43			}
44		}
45		if err := s.Close(); err != nil {
46			t.Fatal(err)
47		}
48		return dir
49	}
